CREATE TABLE "AgentConfigVersion" ("id" UUID NOT NULL, "scope" TEXT NOT NULL, "scopeKey" TEXT NOT NULL, "agentKey" TEXT NOT NULL, "version" TEXT NOT NULL, "content" TEXT NOT NULL, "contentHash" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "lintReport" JSONB NOT NULL DEFAULT '{}', "evalReport" JSONB NOT NULL DEFAULT '{}', "approvedBy" UUID, "activatedAt" TIMESTAMP(3), "createdBy" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AgentConfigVersion_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AgentConfigVersion_scope_scopeKey_agentKey_version_key" ON "AgentConfigVersion"("scope","scopeKey","agentKey","version");
CREATE INDEX "AgentConfigVersion_scope_scopeKey_agentKey_status_idx" ON "AgentConfigVersion"("scope","scopeKey","agentKey","status");
CREATE TABLE "AgentRun" ("id" UUID NOT NULL, "projectId" UUID NOT NULL, "agentKey" TEXT NOT NULL, "configVersionId" UUID, "snapshotId" UUID, "parentRunId" UUID, "status" TEXT NOT NULL DEFAULT 'QUEUED', "modelRoute" TEXT NOT NULL, "promptHash" TEXT NOT NULL, "inputHash" TEXT NOT NULL, "inputRef" JSONB NOT NULL DEFAULT '{}', "outputRef" JSONB NOT NULL DEFAULT '{}', "validation" JSONB NOT NULL DEFAULT '{}', "attempt" INTEGER NOT NULL DEFAULT 1, "tokensIn" INTEGER, "tokensOut" INTEGER, "costCents" INTEGER, "durationMs" INTEGER, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "finishedAt" TIMESTAMP(3), CONSTRAINT "AgentRun_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AgentRun_projectId_agentKey_startedAt_idx" ON "AgentRun"("projectId","agentKey","startedAt"); CREATE INDEX "AgentRun_status_startedAt_idx" ON "AgentRun"("status","startedAt");
CREATE TABLE "AgentFinding" ("id" UUID NOT NULL, "runId" UUID NOT NULL, "targetType" TEXT NOT NULL, "targetId" UUID NOT NULL, "severity" TEXT NOT NULL, "code" TEXT NOT NULL, "message" TEXT NOT NULL, "suggestedFix" TEXT NOT NULL DEFAULT '', "resolution" TEXT, "resolvedBy" UUID, "resolutionNote" TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolvedAt" TIMESTAMP(3), CONSTRAINT "AgentFinding_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AgentFinding_runId_severity_idx" ON "AgentFinding"("runId","severity"); CREATE INDEX "AgentFinding_targetType_targetId_idx" ON "AgentFinding"("targetType","targetId");
CREATE TABLE "AgentModelRoute" ("id" UUID NOT NULL, "organizationId" UUID NOT NULL, "routeKey" TEXT NOT NULL, "displayName" TEXT NOT NULL, "provider" TEXT NOT NULL, "model" TEXT NOT NULL, "baseUrl" TEXT NOT NULL, "credentialRef" TEXT NOT NULL DEFAULT '', "fallbackRouteKey" TEXT NOT NULL DEFAULT '', "maxCostCents" INTEGER NOT NULL DEFAULT 50, "timeoutSeconds" INTEGER NOT NULL DEFAULT 120, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdBy" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AgentModelRoute_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AgentModelRoute_organizationId_routeKey_key" ON "AgentModelRoute"("organizationId","routeKey");
ALTER TABLE "AgentRun" ADD CONSTRAINT "AgentRun_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AgentRun" ADD CONSTRAINT "AgentRun_configVersionId_fkey" FOREIGN KEY ("configVersionId") REFERENCES "AgentConfigVersion"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "AgentRun" ADD CONSTRAINT "AgentRun_parentRunId_fkey" FOREIGN KEY ("parentRunId") REFERENCES "AgentRun"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "AgentFinding" ADD CONSTRAINT "AgentFinding_runId_fkey" FOREIGN KEY ("runId") REFERENCES "AgentRun"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AgentModelRoute" ADD CONSTRAINT "AgentModelRoute_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
